"""Engine rules on synthetic players (no names, no database)."""
import re
from datetime import date, timedelta
from pathlib import Path

import pandas as pd
import pytest

from cmj_flags.engine import (NO_BASELINE, PAIR_CUTS, PAIR_GAP_DAYS, SINGLE_TEST_CUTS, Settings,
                              camp_starts, flag_tests)

CAMP = date(2026, 8, 5)        # a Wednesday; first test on/after Aug 1
MON = date(2026, 8, 24)        # season Mondays start here


def _rows(athlete, values_by_date):
    return [{"athlete_id": athlete, "test_date": d, "pp_bm": v} for d, v in values_by_date]


def _week(n, day):             # n-th season week, day 0 = Monday, 2 = Wednesday
    return MON + timedelta(weeks=n, days=day)


def _season(mon_vals, wed_vals, athlete="a1"):
    rows = [(CAMP, 50.0)]
    for i, (m, w) in enumerate(zip(mon_vals, wed_vals)):
        if m is not None:
            rows.append((_week(i, 0), m))
        if w is not None:
            rows.append((_week(i, 2), w))
    return _rows(athlete, rows)


def _flag(rows, **kw):
    return flag_tests(pd.DataFrame(rows), Settings(**kw))


def test_camp_start_is_first_test_on_or_after_aug_1():
    s = pd.Series([date(2026, 7, 20), date(2026, 8, 5), date(2026, 8, 9), date(2025, 8, 3)])
    assert camp_starts(s, (8, 1)) == {2026: date(2026, 8, 5), 2025: date(2025, 8, 3)}


def test_no_flag_until_two_same_weekday_tests():
    out = _flag(_season([50, 50, 40], [50, 50, 50]))
    mondays = out[out["weekday"] == "Mon"]
    assert list(mondays["tier"][:2]) == [NO_BASELINE, NO_BASELINE]
    assert mondays["baseline"].iloc[2] == 50.0


def test_monday_is_compared_with_mondays_only():
    # Wednesdays run 10% higher; a normal Monday must not look like a 10% drop
    out = _flag(_season([50, 50, 50], [55, 55, 55]))
    assert set(out[out["weekday"] == "Mon"]["tier"][2:]) == {"GREEN"}
    assert set(out[out["weekday"] == "Wed"]["tier"][2:]) == {"GREEN"}


def test_department_pair_rule_needs_both_tests_down():
    # Week 2: Monday -6%, Wednesday -6% -> pair AMBER (>5% both)
    out = _flag(_season([50, 50, 47], [50, 50, 47]))
    wed = out[(out["test_date"] == _week(2, 2))].iloc[0]
    assert wed["evidence"] == "pair" and wed["tier"] == "AMBER"


